/* Lightbox2-compatible implementation
 * Supports: data-lightbox="group", data-title="Caption"
 * Groups images by data-lightbox value for prev/next navigation.
 * Keyboard: ArrowLeft/ArrowRight to navigate, Escape to close.
 */
(function () {
  'use strict';

  var overlay, imgEl, caption, numberEl, prevBtn, nextBtn, loaderEl;
  var groups = {};   // { groupName: [{ src, title, el }] }
  var current = { group: null, index: 0 };

  function buildDOM() {
    overlay = document.createElement('div');
    overlay.className = 'lb-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Image lightbox');

    overlay.innerHTML =
      '<button class="lb-close" aria-label="Close lightbox">' +
        '<svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>' +
      '</button>' +
      '<button class="lb-prev lb-hidden" aria-label="Previous image">' +
        '<svg viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6"/></svg>' +
      '</button>' +
      '<button class="lb-next lb-hidden" aria-label="Next image">' +
        '<svg viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg>' +
      '</button>' +
      '<div class="lb-container">' +
        '<div class="lb-image-wrap">' +
          '<div class="lb-loader"><div class="lb-loader-spin"></div></div>' +
          '<img class="lb-image" alt="" />' +
        '</div>' +
        '<div class="lb-data">' +
          '<span class="lb-caption"></span>' +
          '<span class="lb-number"></span>' +
        '</div>' +
      '</div>';

    document.body.appendChild(overlay);

    imgEl    = overlay.querySelector('.lb-image');
    caption  = overlay.querySelector('.lb-caption');
    numberEl = overlay.querySelector('.lb-number');
    loaderEl = overlay.querySelector('.lb-loader');
    prevBtn  = overlay.querySelector('.lb-prev');
    nextBtn  = overlay.querySelector('.lb-next');

    overlay.querySelector('.lb-close').addEventListener('click', close);

    // Click outside container closes
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) close();
    });

    prevBtn.addEventListener('click', function (e) { e.stopPropagation(); navigate(-1); });
    nextBtn.addEventListener('click', function (e) { e.stopPropagation(); navigate(1); });

    document.addEventListener('keydown', function (e) {
      if (!overlay.classList.contains('lb-active')) return;
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowLeft')  navigate(-1);
      if (e.key === 'ArrowRight') navigate(1);
    });
  }

  function collectGroups() {
    groups = {};
    document.querySelectorAll('a[data-lightbox]').forEach(function (a) {
      var gName = a.getAttribute('data-lightbox');
      var src   = a.getAttribute('href');
      var title = a.getAttribute('data-title') || '';
      if (!groups[gName]) groups[gName] = [];
      groups[gName].push({ src: src, title: title, el: a });
    });
  }

  function open(groupName, index) {
    current.group = groupName;
    current.index = index;
    overlay.classList.add('lb-active');
    document.body.style.overflow = 'hidden';
    loadImage(groups[groupName][index]);
    updateNav();
  }

  function close() {
    overlay.classList.remove('lb-active');
    imgEl.classList.remove('lb-loaded');
    imgEl.src = '';
    document.body.style.overflow = '';
  }

  function navigate(dir) {
    var list = groups[current.group];
    if (!list) return;
    var next = current.index + dir;
    if (next < 0 || next >= list.length) return;
    current.index = next;
    imgEl.classList.remove('lb-loaded');
    loadImage(list[next]);
    updateNav();
  }

  function loadImage(item) {
    loaderEl.style.display = 'flex';
    imgEl.classList.remove('lb-loaded');
    caption.textContent = item.title;
    var list = groups[current.group];
    numberEl.textContent = list.length > 1
      ? (current.index + 1) + ' / ' + list.length
      : '';

    var tmp = new window.Image();
    tmp.onload = function () {
      imgEl.src = item.src;
      imgEl.alt = item.title;
      loaderEl.style.display = 'none';
      imgEl.classList.add('lb-loaded');
    };
    tmp.onerror = function () {
      loaderEl.style.display = 'none';
      imgEl.src = item.src;
      imgEl.alt = item.title;
      imgEl.classList.add('lb-loaded');
    };
    tmp.src = item.src;
  }

  function updateNav() {
    var list = groups[current.group] || [];
    var multi = list.length > 1;
    prevBtn.classList.toggle('lb-hidden', !multi || current.index === 0);
    nextBtn.classList.toggle('lb-hidden', !multi || current.index === list.length - 1);
  }

  function init() {
    buildDOM();
    collectGroups();

    document.addEventListener('click', function (e) {
      var a = e.target.closest('a[data-lightbox]');
      if (!a) return;
      e.preventDefault();
      // Rebuild groups in case DOM changed
      collectGroups();
      var gName = a.getAttribute('data-lightbox');
      var list  = groups[gName] || [];
      var idx   = list.findIndex(function (item) { return item.el === a; });
      open(gName, idx < 0 ? 0 : idx);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
